            self.assertTrue(
                any("private #[cfg(test)] test_set_cell:" in item for item in violations)
            )
            self.assertTrue(
                any("private #[cfg(test)] test_set_cells:" in item for item in violations)
            )
            self.assertTrue(
                any("example calls test-only" in item for item in violations)
            )

